# ---------- STEP 0: Read the output of the cleaning node ----------
src = _items[0]["json"]
try:
    src = src.to_py()      # converts n8n data to normal Python data
except Exception:
    pass

cleaned = src.get("cleaned", [])
profile = src.get("profile", {})
n_rows = len(cleaned)

if n_rows == 0:
    return [{"json": {"error": "No cleaned data received from previous node"}}]


# ---------- Helper functions ----------
def tidy(x):
    x = float(x)
    if x.is_integer():
        return int(x)
    return round(x, 2)


def mean_of(v):
    return sum(v) / len(v)


def std_of(v):
    if len(v) < 2:
        return 0.0
    m = mean_of(v)
    return (sum((x - m) ** 2 for x in v) / (len(v) - 1)) ** 0.5


def skewness(v):
    n = len(v)
    m = mean_of(v)
    s = (sum((x - m) ** 2 for x in v) / n) ** 0.5
    if s == 0:
        return 0.0
    return (sum((x - m) ** 3 for x in v) / n) / (s ** 3)


def kurtosis(v):
    """Excess kurtosis (0 means normal-like tails)."""
    n = len(v)
    m = mean_of(v)
    s = (sum((x - m) ** 2 for x in v) / n) ** 0.5
    if s == 0:
        return 0.0
    return (sum((x - m) ** 4 for x in v) / n) / (s ** 4) - 3


def pearson(a, b):
    ma = mean_of(a)
    mb = mean_of(b)
    num = sum((x - ma) * (y - mb) for x, y in zip(a, b))
    da = sum((x - ma) ** 2 for x in a) ** 0.5
    db = sum((y - mb) ** 2 for y in b) ** 0.5
    if da == 0 or db == 0:
        return 0.0
    return num / (da * db)


# ---------- STEP 1: Separate numeric, categorical and ID columns ----------
numeric_cols = []
categorical_cols = []
id_cols = []
col_values = {}

for col, p in profile.items():
    if p.get("type") == "numeric":
        vals = [float(r[col]) for r in cleaned]
        name = col.lower().replace("_", " ").replace("-", " ")
        looks_like_id = ("id" in name.split() or name.endswith("id")) and len(set(vals)) == len(vals)
        if looks_like_id:
            id_cols.append(col)
        else:
            numeric_cols.append(col)
            col_values[col] = vals
    else:
        categorical_cols.append(col)

findings = []


# ---------- STEP 2: Numeric analysis (shape, spread, outliers) ----------
numeric_analysis = {}

for col in numeric_cols:
    vals = col_values[col]
    m = mean_of(vals)
    sd = std_of(vals)
    sk = skewness(vals)
    ku = kurtosis(vals)
    cv = (sd / abs(m) * 100) if m != 0 else 0

    if abs(sk) < 0.5:
        shape = "roughly symmetric"
    elif abs(sk) < 1:
        shape = "moderately " + ("right" if sk > 0 else "left") + "-skewed"
    else:
        shape = "highly " + ("right" if sk > 0 else "left") + "-skewed"

    q1 = profile[col]["q1"]
    q3 = profile[col]["q3"]
    iqr = q3 - q1
    low_limit = q1 - 1.5 * iqr
    high_limit = q3 + 1.5 * iqr
    outlier_vals = sorted([x for x in vals if x < low_limit or x > high_limit])

    numeric_analysis[col] = {
        "mean": tidy(m),
        "median": profile[col]["median"],
        "std": tidy(sd),
        "min": profile[col]["min"],
        "max": profile[col]["max"],
        "range": tidy(max(vals) - min(vals)),
        "skewness": round(sk, 2),
        "kurtosis": round(ku, 2),
        "shape": shape,
        "coefficient_of_variation_pct": round(cv, 1),
        "outlier_count": len(outlier_vals),
        "outlier_examples": [tidy(x) for x in outlier_vals[:5]],
        "outlier_limits": [tidy(low_limit), tidy(high_limit)],
    }

    if abs(sk) >= 1:
        findings.append('"' + col + '" is ' + shape + " (skewness " + str(round(sk, 2)) + ")")
    if cv > 50:
        findings.append('"' + col + '" varies a lot (coefficient of variation ' + str(round(cv, 1)) + "%)")
    if len(outlier_vals) > 0:
        findings.append('"' + col + '" has ' + str(len(outlier_vals)) + " outlier(s), e.g. "
                        + ", ".join(str(tidy(x)) for x in outlier_vals[:3]))


# ---------- STEP 3: Correlation matrix (up to 12 numeric columns) ----------
corr_cols = numeric_cols[:12]
correlation_matrix = {}
pairs = []

for a in corr_cols:
    correlation_matrix[a] = {}
    for b in corr_cols:
        if a == b:
            correlation_matrix[a][b] = 1.0
        else:
            correlation_matrix[a][b] = round(pearson(col_values[a], col_values[b]), 2)

for i in range(len(corr_cols)):
    for j in range(i + 1, len(corr_cols)):
        a = corr_cols[i]
        b = corr_cols[j]
        r = correlation_matrix[a][b]
        if abs(r) >= 0.5:
            strength = "strong" if abs(r) >= 0.7 else "moderate"
            direction = "positive" if r > 0 else "negative"
            pairs.append({"column_1": a, "column_2": b, "r": r,
                          "description": strength + " " + direction})

pairs.sort(key=lambda p: abs(p["r"]), reverse=True)
notable_correlations = pairs[:10]

for p in notable_correlations[:3]:
    findings.append(p["description"].capitalize() + ' correlation between "' + p["column_1"]
                    + '" and "' + p["column_2"] + '" (r = ' + str(p["r"]) + ")")


# ---------- STEP 4: Categorical analysis ----------
categorical_analysis = {}

for col in categorical_cols:
    counts = {}
    for r in cleaned:
        key = str(r[col])
        counts[key] = counts.get(key, 0) + 1
    ranked = sorted(counts.items(), key=lambda kv: kv[1], reverse=True)

    top3 = []
    for value, count in ranked[:3]:
        top3.append({"value": value, "count": count, "percent": round(count / n_rows * 100, 1)})

    note = ""
    if ranked[0][1] / n_rows > 0.7:
        note = "dominated by one value"
        findings.append('"' + col + '" is dominated by "' + ranked[0][0] + '" ('
                        + str(round(ranked[0][1] / n_rows * 100, 1)) + "% of rows)")
    elif len(ranked) > n_rows * 0.5:
        note = "very many unique values, may be an identifier or free text"

    categorical_analysis[col] = {"unique": len(ranked), "top3": top3, "note": note}


# ---------- STEP 5: Group comparison (average of numbers per category) ----------
group_summary = {}
group_cats = [c for c in categorical_cols if categorical_analysis[c]["unique"] <= 10][:3]
group_nums = numeric_cols[:3]
group_findings = 0

for cat in group_cats:
    group_summary[cat] = {}
    for num in group_nums:
        buckets = {}
        for r in cleaned:
            buckets.setdefault(str(r[cat]), []).append(float(r[num]))
        averages = {g: tidy(mean_of(v)) for g, v in buckets.items()}
        group_summary[cat][num] = averages

        if len(averages) >= 2 and group_findings < 5:
            best = max(averages, key=lambda g: averages[g])
            worst = min(averages, key=lambda g: averages[g])
            findings.append('Average "' + num + '" by "' + cat + '": highest in "' + best + '" ('
                            + str(averages[best]) + "), lowest in \"" + worst + '" (' + str(averages[worst]) + ")")
            group_findings += 1


# ---------- STEP 6: Data quality finding ----------
findings.insert(0, "Data quality score is " + str(src.get("quality_score")) + "/100; "
                + str(src.get("duplicates_removed")) + " duplicate rows removed and "
                + str(src.get("cells_filled")) + " missing cells filled")


# ---------- STEP 7: Return everything ----------
return [{
    "json": {
        "overview": {
            "rows_before": src.get("rows_before"),
            "rows_after": src.get("rows_after"),
            "columns_after": src.get("columns_after"),
            "numeric_columns": len(numeric_cols),
            "categorical_columns": len(categorical_cols),
            "duplicates_removed": src.get("duplicates_removed"),
            "cells_filled": src.get("cells_filled"),
            "columns_dropped": src.get("columns_dropped"),
            "quality_score": src.get("quality_score"),
        },
        "key_findings": findings,
        "numeric_analysis": numeric_analysis,
        "correlation_matrix": correlation_matrix,
        "notable_correlations": notable_correlations,
        "categorical_analysis": categorical_analysis,
        "group_summary": group_summary,
        "skipped_id_columns": id_cols,
        "cleaning_log": src.get("cleaning_log"),
        "cleaned": cleaned,
    }
}]

