const md = $input.first().json.text || '';

let h = md
  .replace(/^### (.*)$/gm, '<h3>$1</h3>')
  .replace(/^## (.*)$/gm, '<h2>$1</h2>')
  .replace(/^# (.*)$/gm, '<h1>$1</h1>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/`([^`]+)`/g, '<code>$1</code>')
  .replace(/^---$/gm, '<hr>')
  .replace(/^\s*[\*\-] (.*)$/gm, '<li>$1</li>')
  .replace(/^\s*\d+\. (.*)$/gm, '<li>$1</li>')
  .replace(/(<li>.*<\/li>\n?)+/g, function (m) { return '<ul>' + m + '</ul>'; });

h = h.split('\n').map(function (line) {
  const t = line.trim();
  return t && !t.startsWith('<') ? '<p>' + t + '</p>' : line;
}).join('\n');

return [{ json: { data: h } }];
